theme.css:
/* theme: Divided Dawn | A market rally on one side, a government split on the other, the page balanced in grey with a single red rule marking the divide. */
/* mood: neutral */
/* layout: hero=classic; major-events=numbered/grid-2; political-news=lede/stack; financial-news=stat/stack; entertainment-news=outline/grid-2; sports=timeline/stack; music-releases=plain/stack; stock-analysis=stat/masonry; outlook=tile/stack */

.diary-page {
  --paper: #f5f5f5;
  --paper-alt: #ebebeb;
  --ink: #1a1a1a;
  --ink-soft: #3a3a3a;
  --muted: #636363;
  --accent: #1a1a1a;
  --accent-ink: #f5f5f5;
  --rule: #d4d4d4;
  --font-display: var(--ff-instrument), Georgia, serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-inter), system-ui, sans-serif;
}

/* A quiet grey wash on the header, no tint, just depth */
.diary-page .diary-hero {
  background:
    linear-gradient(135deg, rgba(0, 0, 0, 0.05) 0%, rgba(0, 0, 0, 0.01) 45%, rgba(0, 0, 0, 0.03) 100%),
    var(--paper-alt);
  border-bottom: 2px solid var(--ink);
}

.diary-page .diary-hero-inner {
  padding-block: 2.5rem 3.5rem;
}

.diary-page .diary-kicker {
  font-size: 0.7rem;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--ink);
  margin-top: 1.5rem;
}

.diary-page .diary-title {
  font-family: var(--font-display);
  font-weight: 400;
  font-size: clamp(2.6rem, 7vw, 5.5rem);
  line-height: 0.95;
  letter-spacing: -0.01em;
  max-width: none;
  position: relative;
  padding-bottom: 0.75rem;
  border-bottom: 1px solid var(--rule);
}

/* A split rule under the title: half black, half grey, like the election map */
.diary-page .diary-title::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: -2px;
  width: 50%;
  height: 4px;
  background: var(--ink);
}

.diary-page .diary-summary {
  font-size: clamp(1.1rem, 1.8vw, 1.35rem);
  max-width: 40rem;
  color: var(--ink-soft);
  line-height: 1.6;
}

.diary-page .diary-theme-note {
  margin-top: 1.25rem;
  font-size: 0.8rem;
  color: var(--muted);
}

.diary-page .diary-theme-name {
  background: var(--ink);
  color: var(--paper);
  border-radius: 0;
  padding: 0.2rem 0.8rem;
  font-weight: 600;
  letter-spacing: 0.05em;
}

/* Section headers: oversized numerals, quiet titles */
.diary-page .diary-section {
  padding-block: 2.5rem;
  border-top: 1px dashed var(--rule);
}

.diary-page .diary-section:first-child {
  border-top: 0;
}

.diary-page .diary-section-head {
  align-items: center;
  margin-bottom: 2rem;
}

.diary-page .diary-section-number {
  font-family: var(--font-display);
  font-size: 2rem;
  font-weight: 400;
  color: var(--rule);
  letter-spacing: 0;
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-weight: 400;
  font-size: clamp(1.8rem, 3vw, 2.5rem);
  letter-spacing: -0.015em;
}

/* Major events: numbered cards in a close grid, like a roll of votes */
.diary-page [data-section="major-events"] .diary-card--numbered {
  border-top: 2px solid var(--rule);
  padding-top: 0.75rem;
}

.diary-page [data-section="major-events"] .diary-card-index {
  font-family: var(--font-display);
  font-weight: 400;
  font-size: 2.6rem;
  color: var(--muted);
  line-height: 0.85;
}

.diary-page [data-section="major-events"] .diary-card-title {
  font-size: 1.2rem;
  line-height: 1.3;
  color: var(--ink);
}

.diary-page [data-section="major-events"] .diary-card-body {
  font-size: 1rem;
  line-height: 1.6;
  color: var(--ink-soft);
}

/* Political news: a long-form lede, centred column */
.diary-page [data-section="political-news"] .diary-card--lede {
  max-width: 38rem;
}

.diary-page [data-section="political-news"] .diary-card-lede {
  font-family: var(--font-display);
  font-weight: 400;
  font-size: 1.6rem;
  line-height: 1.4;
  border-left: 0;
  padding-left: 0;
  max-width: 32rem;
  color: var(--ink);
}

.diary-page [data-section="political-news"] .diary-card-body {
  font-size: 1.12rem;
  line-height: 1.8;
  max-width: 38rem;
}

/* Financial news: a stat card, figure first, like a ticker */
.diary-page [data-section="financial-news"] .diary-card--stat {
  border-top: 4px solid var(--ink);
  padding-top: 0.5rem;
  max-width: 38rem;
}

.diary-page [data-section="financial-news"] .diary-card-figure {
  font-family: var(--font-display);
  font-weight: 400;
  font-size: clamp(2.5rem, 8cqi, 4rem);
  color: var(--ink);
  letter-spacing: -0.02em;
}

.diary-page [data-section="financial-news"] .diary-card-body {
  font-size: 1.1rem;
  line-height: 1.75;
}

/* Entertainment: outlined cards, a touch of stage-light grey */
.diary-page [data-section="entertainment-news"] .diary-card--outline .diary-card-inner {
  border: 1px solid var(--rule);
  border-radius: 0;
  background: var(--paper);
  padding: 1.25rem;
}

.diary-page [data-section="entertainment-news"] .diary-card-title {
  font-size: 1.3rem;
  line-height: 1.25;
}

/* Sports: a vertical timeline of scores, dots like whistle-stops */
.diary-page [data-section="sports"] .diary-card--timeline .diary-card-inner {
  padding-left: 2rem;
}

.diary-page [data-section="sports"] .diary-card--timeline .diary-card-inner::before {
  left: 0.4rem;
  background: var(--rule);
}

.diary-page [data-section="sports"] .diary-card--timeline .diary-card-inner::after {
  left: 0;
  width: 0.6rem;
  height: 0.6rem;
  background: var(--ink);
  box-shadow: 0 0 0 3px var(--paper);
}

.diary-page [data-section="sports"] .diary-card-title {
  font-family: var(--font-body);
  font-size: 1.15rem;
  font-weight: 400;
  color: var(--ink-soft);
}

.diary-page [data-section="sports"] .diary-card-body {
  font-size: 1rem;
}

/* Music: plain, unboxed, a breath of air */
.diary-page [data-section="music-releases"] .diary-card--plain {
  max-width: 38rem;
}

.diary-page [data-section="music-releases"] .diary-card-body {
  font-size: 1.05rem;
}

/* Stock analysis: a masonry of stat cards, figures in the air */
.diary-page [data-section="stock-analysis"] .diary-stories--masonry {
  columns: 2 16rem;
  column-gap: 1.5rem;
}

.diary-page [data-section="stock-analysis"] .diary-card--stat {
  border-top: 1px solid var(--rule);
  padding-top: 0.5rem;
  break-inside: avoid;
  margin-bottom: 1.25rem;
}

.diary-page [data-section="stock-analysis"] .diary-card-figure {
  font-size: clamp(1.8rem, 8cqi, 2.8rem);
  font-weight: 400;
  color: var(--ink);
}

.diary-page [data-section="stock-analysis"] .diary-card-title {
  font-size: 1rem;
  font-family: var(--font-body);
  font-weight: 400;
  color: var(--ink-soft);
}

.diary-page [data-section="stock-analysis"] .diary-card-body {
  font-size: 0.95rem;
  line-height: 1.6;
  color: var(--muted);
}

/* Outlook: solid tiles, a quiet end of the page */
.diary-page [data-section="outlook"] .diary-card--tile .diary-card-inner {
  background: var(--paper-alt);
  border-left: 3px solid var(--ink);
  padding: 1rem 1.25rem;
  border-radius: 0;
}

.diary-page [data-section="outlook"] .diary-card-title {
  font-size: 1.15rem;
  font-weight: 400;
  color: var(--ink);
}

.diary-page [data-section="outlook"] .diary-card-body {
  font-size: 1rem;
  line-height: 1.65;
  color: var(--ink-soft);
}

/* Contents rail: quiet and thin */
.diary-page .diary-toc {
  border-bottom: 1px solid var(--rule);
}

.diary-page .diary-toc-link.is-active {
  color: var(--ink);
}

.diary-page .diary-toc-number {
  color: var(--muted);
}

/* Citations, in the ink colour family */
.diary-page .diary-prose a {
  color: var(--ink);
  border-bottom: 1px solid var(--rule);
}

.diary-page .diary-prose a:hover {
  color: var(--muted);
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--muted);
}

.diary-page .diary-prose ol > li::marker {
  color: var(--muted);
}

/* Footer, bookended */
.diary-page .diary-footer {
  border-top: 1px solid var(--rule);
  color: var(--muted);
}

.diary-page .diary-footer a {
  color: var(--ink);
}

.diary-page .diary-footer a:hover {
  color: var(--muted);
}

/* One quiet entrance: the title settles in */
@media (prefers-reduced-motion: no-preference) {
  .diary-page .diary-title {
    animation: diary-settle 0.5s ease-out both;
  }

  @keyframes diary-settle {
    from {
      opacity: 0;
      transform: translateY(0.5rem);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }
}
